import {useCallback, useMemo} from 'react'
import {clsx} from 'clsx'
import {ActionList, Button, IconButton, ActionMenu} from '@primer/react'
import {ChevronRightIcon, GitBranchIcon, KebabHorizontalIcon, PencilIcon, TrashIcon} from '@primer/octicons-react'
import {PanelList} from '@github-ui/panel-list'
import {Page, type CopilotModelRule} from '../../types'
import {InlineModelSummary} from '../inlineSummary/InlineModelSummary'
import {InlineOrganizationSummary} from '../inlineSummary/InlineOrganizationSummary'
import {useModels} from '../../hooks/use-models'
import {useConfirmableNavigate} from '../../hooks/use-confirmable-navigate'
import {usePermissions} from '../../contexts/PermissionsContext'
import {useOrganizations} from '../../hooks/use-organizations'
import {useSettings} from '../../hooks/use-settings'
import styles from './RulesPanel.module.css'
import {useRuleLabel} from '../../hooks/use-rule-label'
import {useLoading} from '../../contexts/LoadingContext'

export function RulesPanel() {
  const {setting} = useSettings()
  const confirmableNavigate = useConfirmableNavigate()
  const {canWrite} = usePermissions()
  const {isLoading} = useLoading()
  const rules = setting?.rules ?? []

  return (
    <PanelList
      title="Targeted model rules"
      subtitle="Create rules to control which models are available to which organizations"
      boxTitle="Rules"
      isEmpty={rules.length === 0}
      isLoading={isLoading}
      isPreview
    >
      <PanelList.HeaderActions>
        <Button variant="primary" onClick={() => confirmableNavigate(Page.CreateRule)} disabled={!canWrite}>
          Create access rule
        </Button>
      </PanelList.HeaderActions>
      <PanelList.Rows>
        {rules.map(rule => (
          <RuleRow key={rule.id} rule={rule} />
        ))}
      </PanelList.Rows>
      <PanelList.Blankslate
        heading="No rules created"
        description="Create rules to control which models are available to which organizations"
      >
        <PanelList.Blankslate.Actions onClick={() => confirmableNavigate(Page.CreateRule)} disabled={!canWrite}>
          Create rule
        </PanelList.Blankslate.Actions>
      </PanelList.Blankslate>
    </PanelList>
  )
}

function RuleRow({rule}: {rule: CopilotModelRule}) {
  const {selectedModels} = useModels(rule.parameters.values)
  const {organizationMap} = useOrganizations()
  const orgs = useMemo(
    () => rule.conditionExpression.value.split(',').map(org => organizationMap.get(org) ?? {name: org}),
    [rule.conditionExpression.value, organizationMap],
  )
  const isSingleOrg = orgs.length === 1

  return (
    <PanelList.Row key={rule.id} className={styles.RowContainer}>
      <PanelList.Row.LeadingVisual>
        <GitBranchIcon className={clsx(styles.BranchIcon, 'mt-1 color-fg-muted')} />
      </PanelList.Row.LeadingVisual>
      <div className="d-flex flex-row flex-items-center gap-1">
        <InlineOrganizationSummary organizations={orgs} />
        <span className={clsx(styles.AccessToText, 'fgColor-muted')}>{`${
          isSingleOrg ? 'has' : 'have'
        } access to`}</span>
        <span className={styles.AccessToTextMinimized}>•</span>
        <InlineModelSummary selectedModels={selectedModels} className="flex-1" />
      </div>
      <PanelList.Row.Actions>
        <RuleActions rule={rule} />
      </PanelList.Row.Actions>
    </PanelList.Row>
  )
}

function RuleActions({rule}: {rule: CopilotModelRule}) {
  const confirmableNavigate = useConfirmableNavigate()
  const {setting, updateSetting} = useSettings()
  const {canWrite} = usePermissions()
  const ruleLabel = useRuleLabel(rule)

  const removeRule = useCallback(() => {
    updateSetting({
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      ...setting!,
      rules: setting?.rules.filter(r => r.id !== rule.id) ?? [],
    })
  }, [updateSetting, rule, setting])

  return (
    <ActionMenu>
      <ActionMenu.Anchor>
        <IconButton variant="invisible" icon={KebabHorizontalIcon} aria-label={`Open menu for ${ruleLabel}`} />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay width="auto">
        <ActionList>
          <ActionList.Item onSelect={() => confirmableNavigate(Page.UpdateRule, rule.id)}>
            <ActionList.LeadingVisual>{canWrite ? <PencilIcon /> : <ChevronRightIcon />}</ActionList.LeadingVisual>
            <span>{canWrite ? 'Edit' : 'View'}</span>
          </ActionList.Item>
          <ActionList.Item onSelect={() => removeRule()} variant="danger" disabled={!canWrite}>
            <ActionList.LeadingVisual>
              <TrashIcon />
            </ActionList.LeadingVisual>
            Delete
          </ActionList.Item>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
