import type {FC} from 'react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {Publisher} from '../types'

export const publisherMap: Record<Publisher, {src: string; alt: string}> = {
  [Publisher.OpenAI]: {
    src: '/images/modules/marketplace/models/families/openai.svg',
    alt: 'OpenAI logo',
  },
  [Publisher.Anthropic]: {
    src: '/images/modules/marketplace/models/families/anthropic.svg',
    alt: 'Anthropic logo',
  },
  [Publisher.Gemini]: {
    src: '/images/modules/marketplace/models/families/gemini.svg',
    alt: 'Gemini logo',
  },
  [Publisher.xAI]: {
    src: '/images/modules/marketplace/models/families/xai.svg',
    alt: 'xAI logo',
  },
}

export const PublisherIcon: FC<{publisher: Publisher}> = ({publisher}) => {
  const {src, alt} = publisherMap[publisher] ?? {}
  return <GitHubAvatar square alt={alt} size={16} src={src} />
}
