import {Breadcrumbs, PageHeader} from '@primer/react'
import {Outlet} from '@github-ui/react-router'
import {AppProvider} from '../components/AppProvider'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {NavTabs} from '../components/NavTabs'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import type {AppPayload} from '../types'
import {ReadOnlyBanner} from '../components/ReadOnlyBanner'
import {PartialRouterProvider} from '../contexts/PartialRouteContext'

export function Layout() {
  const {isAdmin, canWrite, isStafftools, paths} = useAppPayload<AppPayload>()
  const isUnconfiguredSeparate = !isFeatureEnabled('copilot_unconfigured_is_inherited')

  return (
    <AppProvider canWrite={!isStafftools && canWrite} enabledFeatures={{isUnconfiguredSeparate}} paths={paths}>
      <PartialRouterProvider>
        {!isStafftools && !isAdmin && <ReadOnlyBanner />}
        {!isStafftools && (
          <Breadcrumbs>
            <Breadcrumbs.Item href="..">Copilot</Breadcrumbs.Item>
            <Breadcrumbs.Item href="." aria-current="page">
              Models
            </Breadcrumbs.Item>
          </Breadcrumbs>
        )}
        <PageHeader hasBorder className="my-2">
          <PageHeader.Title as="h1">Models</PageHeader.Title>
        </PageHeader>
        {!isStafftools && <NavTabs />}
        <div className="d-flex flex-column gap-3">
          <Outlet />
        </div>
      </PartialRouterProvider>
    </AppProvider>
  )
}
