import {useMemo} from 'react'
import {type Model, type CopilotModelValue, ModelValue, type ModelWithValue} from '../types'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {usePathsContext} from '../contexts/PathsContext'
import {useLoading} from '../contexts/LoadingContext'

export function useModels(selectedModels?: CopilotModelValue) {
  const {modelsPath} = usePathsContext()
  const {setIsLoading} = useLoading()
  const {data: models, isFetching} = useQuery({
    queryKey: ['default-model-settings', 'models', modelsPath],
    queryFn: async () => {
      setIsLoading(true)
      const response = await verifiedFetchJSON(modelsPath)

      if (!response.ok) {
        throw new Error(`Failed to retrieve models (${response.status} on ${response.url})`)
      }

      const newModels = (await response.json()) as Model[]
      setIsLoading(false)
      return newModels
    },
    placeholderData: [],
    staleTime: Infinity,
  })

  return useMemo(() => {
    const _models = models ?? [] // default value assignment in the render method breaks memoization
    const mappedModels: ModelWithValue[] = selectedModels
      ? _models.map(model => ({
          ...model,
          value: selectedModels[model.name] || ModelValue.Unconfigured,
        }))
      : []
    const mappedSelectedModels: ModelWithValue[] = mappedModels.filter(
      model => model.value === ModelValue.Enabled || model.value === ModelValue.NoPolicy,
    )
    return {
      selectedModels: mappedSelectedModels,
      models: mappedModels,
      isSyncing: isFetching,
    }
  }, [selectedModels, models, isFetching])
}
