import {useMemo} from 'react'
import {useModels} from './use-models'
import type {CopilotModelRule} from '../types'

export const MAX_SUMMARY_ITEMS = 2

export function useRuleLabel(rule: CopilotModelRule): string {
  const {selectedModels} = useModels(rule.parameters.values)

  return useMemo(() => {
    const orgList = rule.conditionExpression.value.split(',')
    const organizations =
      orgList.length <= MAX_SUMMARY_ITEMS
        ? `${orgList.length > 1 ? 'organizations ' : ''}${orgList.join(' and ')}`
        : `${orgList.length} organizations`

    const models =
      selectedModels.length <= MAX_SUMMARY_ITEMS
        ? `${selectedModels.length > 1 ? 'models ' : ''}${selectedModels.map(model => model.displayName).join(' and ')}`
        : `${selectedModels.length} models`

    return `rule targeting ${organizations} for ${models}`
  }, [selectedModels, rule.conditionExpression.value])
}
