import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {defaultModelSettingsAppBuilder} from './config/app-builder'

import {layoutRoute} from './routes/layout-route'
import {Layout} from './routes/layout'

import {overviewRoute, stafftoolsOverviewRoute} from './routes/overview-route'
import {Overview} from './routes/overview'
import {ruleRoute, stafftoolsRuleRoute} from './routes/rule-route'
import {Rule} from './routes/rule'

export const defaultModelSettingsApp = defaultModelSettingsAppBuilder.createDataRouterAppFromRoutes([
  layoutRoute.toRoute({
    Component: Layout,
    children: [
      overviewRoute.toRoute({Component: Overview}),
      ruleRoute.toRoute({Component: Rule}),
      stafftoolsOverviewRoute.toRoute({Component: Overview}),
      stafftoolsRuleRoute.toRoute({Component: Rule}),
    ],
  }),
])
registerDataRouterApp(defaultModelSettingsApp)
