import {useMemo} from 'react'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {BaseOrganization} from '@github-ui/org-selector'
import {usePathsContext} from '../contexts/PathsContext'
import {useLoading} from '../contexts/LoadingContext'

export function useOrganizations() {
  const {organizationsPath} = usePathsContext()
  const {setIsLoading} = useLoading()
  const {data: organizations, isFetching} = useQuery({
    queryKey: ['default-model-settings', 'organizations', organizationsPath],
    queryFn: async () => {
      setIsLoading(true)
      const response = await verifiedFetchJSON(organizationsPath)

      if (!response.ok) {
        throw new Error(`Failed to retrieve organizations (${response.status} on ${response.url})`)
      }

      const orgs = (await response.json()) as BaseOrganization[]
      setIsLoading(false)
      return orgs.sort((a, b) => a.name.localeCompare(b.name))
    },
    placeholderData: [],
    staleTime: Infinity,
  })

  const organizationMap = useMemo<Map<string, BaseOrganization>>(() => {
    const map = new Map()
    if (!organizations) return map
    for (const org of organizations) {
      map.set(org.name, org)
    }
    return map
  }, [organizations])

  return useMemo(
    () => ({
      organizations: organizations ?? [],
      organizationMap,
      isSyncing: isFetching,
    }),
    [organizations, organizationMap, isFetching],
  )
}
