import {mainQuery} from '@github-ui/react-core/future/main-query'
import {defaultModelSettingsAppBuilder} from '../config/app-builder'
import type {BaseOrganization} from '@github-ui/org-selector'
import type {CopilotModelSetting, Model} from '../types'

export type RuleResponse = {
  models: Model[]
  organizations: BaseOrganization[]
  settings: CopilotModelSetting
}

export const ruleRoute = defaultModelSettingsAppBuilder.createQueryRouteConfig('ruleRoute', {
  path: '/enterprises/:slug/ai-controls/copilot/models/rules/:rule_id',
  queries: [mainQuery<RuleResponse>()],
})

export const stafftoolsRuleRoute = defaultModelSettingsAppBuilder.createQueryRouteConfig('stafftoolsRuleRoute', {
  path: '/stafftools/enterprises/:slug/copilot/default_models/rules/:rule_id',
  queries: [mainQuery<RuleResponse>()],
})
