import {Fragment} from 'react'
import {clsx} from 'clsx'
import {AvatarStack} from '@primer/react'
import {GitHubAvatar, type GitHubAvatarProps} from '@github-ui/github-avatar'
import {MAX_SUMMARY_ITEMS} from '../../hooks/use-rule-label'
import styles from './InlineSummary.module.css'

export type SummaryItem = GitHubAvatarProps & {
  key: string
  displayName: string
}

type InlineSummaryProps = {
  items: SummaryItem[]
  title: string
  shape?: 'circle' | 'square'
  showFirstItem?: boolean
  className?: string
}

export function InlineSummary({items, title, shape = 'circle', showFirstItem = false, className}: InlineSummaryProps) {
  if (items.length <= MAX_SUMMARY_ITEMS) {
    return (
      <div className={clsx(className, 'd-flex flex-row flex-items-center gap-1 flex-wrap')}>
        <span className={clsx(styles.SummaryTitle, 'fgColor-muted')}>{title}</span>
        <span className="d-flex flex-row flex-wrap gap-1">
          {items.map(({displayName, key, ...item}, index) => (
            <Fragment key={key}>
              <span className="d-flex flex-row flex-items-center gap-1">
                <span className="d-flex flex-row flex-items-center gap-1">
                  <GitHubAvatar square={shape === 'square'} {...item} />
                  <span className="text-semibold">{displayName}</span>
                </span>
                {index === items.length - 2 && <span className={clsx(styles.AndText, 'fgColor-muted')}>and </span>}
              </span>
            </Fragment>
          ))}
        </span>
      </div>
    )
  }

  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- items.length >= MAX_SUMMARY_ITEMS
  const {key: firstItemKey, displayName: firstDisplayName, ...firstItem}: SummaryItem = items[0]!
  const nextItems: SummaryItem[] = items.slice(1, MAX_SUMMARY_ITEMS + 1)
  return (
    <div className="d-flex flex-row flex-items-center gap-1 flex-wrap">
      {showFirstItem && <span className={styles.SummaryTitle}>{title}</span>}
      {showFirstItem && (
        <span key={firstItemKey} className="d-flex flex-row flex-items-center gap-1">
          <GitHubAvatar square={shape === 'square'} {...firstItem} />
          <span>
            <span className="text-semibold">{firstDisplayName}</span>
          </span>
        </span>
      )}
      <span className="d-flex flex-row flex-items-center gap-1">
        {showFirstItem && <span className="fgColor-muted">and </span>}
        <AvatarStack disableExpand size={16} shape={shape} variant="stack">
          {/* Have to pass GitHubAvatar directly otherwise AvatarStack doesn't work */}
          {nextItems.map(({key, displayName, ...avatarProps}) => (
            <GitHubAvatar className={styles.StackedAvatar} key={key} {...avatarProps} />
          ))}
        </AvatarStack>
        {showFirstItem ? (
          <span className="text-semibold">{items.length - 1} more</span>
        ) : (
          <span className="text-semibold">
            {items.length} {title}
          </span>
        )}
      </span>
    </div>
  )
}
