import {type PropsWithChildren, createContext, useCallback, use, useMemo, useState} from 'react'
import {Page, type AppPayload, type PartialRouter} from '../types'
import {useNavigate} from '@github-ui/use-navigate'
import {useParams} from '@github-ui/react-router'
import {overviewRoute, stafftoolsOverviewRoute} from '../routes/overview-route'
import {ruleRoute, stafftoolsRuleRoute} from '../routes/rule-route'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {useBannerContext} from './BannerContext'

export const PartialRouterContext = createContext<PartialRouter>({
  page: Page.Overview,
  ruleId: undefined,
  navigate() {},
})

export function PartialRouterProvider({children}: PropsWithChildren) {
  const params = useParams()
  const navigate = useNavigate()
  const {clearBanner} = useBannerContext()
  const {isStafftools} = useAppPayload<AppPayload>()

  const slug = params.slug as string
  const rule_id = params.rule_id
  const createRule = rule_id === 'create'

  const [page, setPage] = useState<Page>(!rule_id ? Page.Overview : createRule ? Page.CreateRule : Page.UpdateRule)
  const [ruleId, setRuleId] = useState<number | undefined>(rule_id ? +rule_id : undefined)

  const navigateCallback = useCallback(
    (newPage: Page, newRuleId?: number) => {
      setPage(newPage)
      setRuleId(newRuleId)
      clearBanner()
      if (newPage === Page.Overview) {
        navigate((isStafftools ? stafftoolsOverviewRoute : overviewRoute).generatePath({slug}))
      } else if (newPage === Page.CreateRule) {
        navigate(ruleRoute.generatePath({slug, rule_id: 'new'}))
      } else {
        navigate((isStafftools ? stafftoolsRuleRoute : ruleRoute).generatePath({slug, rule_id: String(newRuleId)}))
      }
    },
    [navigate, slug, isStafftools, clearBanner],
  )

  const value = useMemo(
    () => ({
      page,
      ruleId,
      navigate: navigateCallback,
    }),
    [page, ruleId, navigateCallback],
  )
  return <PartialRouterContext value={value}>{children}</PartialRouterContext>
}

export function usePartialRouter(): PartialRouter {
  const context = use(PartialRouterContext)
  if (!context) {
    throw new Error('usePartialRouter must be used within a PartialRouterProvider')
  }
  return context
}
