import {useCallback, useMemo} from 'react'
import {ModelsPanel} from '../components/panels/ModelsPanel'
import {RulesPanel} from '../components/panels/RulesPanel'
import {useSettings} from '../hooks/use-settings'
import type {CopilotModelSetting, CopilotModelValue} from '../types'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'

export function Overview() {
  const {setting, updateSetting, setValue} = useSettings()
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isModelRulesPreviewEnabled = useFeatureFlag('use_setting_rules_copilot_models')

  const selectedModels = useMemo(() => setting?.value ?? {}, [setting?.value])

  const setModels = useCallback(
    (updatedModels: CopilotModelValue) => {
      setValue({
        ...selectedModels,
        ...updatedModels,
      })
      updateSetting({
        ...setting,
        value: {
          ...selectedModels,
          ...updatedModels,
        },
      } as CopilotModelSetting)
    },
    [selectedModels, setValue, setting, updateSetting],
  )

  return (
    <>
      <ModelsPanel
        selectedModels={selectedModels}
        setModels={setModels}
        showEnterpriseHeader
        showDisabledModels
        showStatus
      />
      {isModelRulesPreviewEnabled && <RulesPanel />}
    </>
  )
}
